const J=(o:any,s=200)=>new Response(JSON.stringify(o),{status:s,headers:{...C,'Content-Type':'application/json; charset=utf-8'}});
const hash=async(s:string)=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))).map(b=>b.toString(16).padStart(2,'0')).join('');
const token=()=>crypto.randomUUID()+crypto.randomUUID();
const teams=['Правящая элита','Оппозиция','Бизнес-элита','Медиа и гражданское общество','Силовые структуры'];
const teamNamesFor=(s:any)=>s.government===1?['Оппозиция (бывшая правящая элита)','Правящая элита (бывшая оппозиция)',...teams.slice(2)]:teams;
const oppositionTeam=(s:any)=>s.government===1?0:1;
const effectiveRole=(s:any,team:number)=>s.government===1&&team<2?1-team:team;
