const ROLE_IMPACT=[[[0,0,0],[0,0,0],[0,0,0]],[[2,0,1],[-2,0,-2],[1,0,1]],[[0,-1,0],[-1,2,0],[0,1,1]],[[2,0,1],[-2,0,-1],[2,0,1]],[[0,0,2],[-1,0,-2],[0,0,1]]];
const MEDIA_IMPACT_BY_ROUND=[[[3,-1,1],[-2,1,-1],[3,-1,2]],[[0,1,1],[2,-2,-1],[2,1,1]],[[2,0,2],[-3,1,-2],[3,-1,0]],[[2,1,1],[-1,-2,0],[2,-1,1]],[[2,0,1],[-3,1,-2],[3,-1,1]],[[0,1,-1],[2,0,2],[2,-1,1]],[[3,-2,1],[-3,1,-2],[2,1,2]],[[2,1,2],[-3,-1,-2],[2,-1,1]]];
function roleEffect(round:number,team:number,option:number){return team===3?MEDIA_IMPACT_BY_ROUND[round][option]:ROLE_IMPACT[team][option];}
function isLegacyCurrent(s:any){return s.roleModeFromRound==null && s.phase==='voting' && s.players.some((p:any)=>s.votes?.[s.round+':'+p.id]!==undefined);}
function isRoleCurrent(s:any){return s.roleModeFromRound!=null ? s.round>=s.roleModeFromRound : !isLegacyCurrent(s);}
const CRISIS_DOSSIERS=[{"lead":"В аппарат президента поступили материалы о закупках оборудования для трёх государственных больниц. Контракт выиграла компания, связанная с родственником министра социальной политики. Правительство утверждает, что оборудование поставлено, оппозиция требует немедленной отставки. Журналисты опубликовали часть переписки, но подлинность двух ключевых писем пока не установлена.","context":"Скандал разгорелся за несколько недель до обсуждения бюджета. Отставка министра может разрушить договорённость внутри кабинета и остановить закупки лекарств. Защита министра позволит сохранить административную непрерывность, но породит подозрения в сокрытии нарушений. Независимое расследование потребует временного ограничения доступа к документам и отложит кадровое решение.","facts":["Контракт на 4,8 млрд условных денежных единиц заключён без открытого конкурса со ссылкой на срочность закупок.","Поставка 70% оборудования подтверждена больницами; цена оставшихся позиций оспаривается аудиторами.","Подпись министра на разрешении о закупке подлинна. Сведения о личном обогащении не подтверждены.","Правительственная коалиция разделилась: часть депутатов готова поддержать проверку, но не отставку."],"uncertain":["Редакция располагает скриншотами переписки; исходные файлы пока не переданы следствию.","Министерство заявляет об отсутствии ущерба. Независимые эксперты допускают завышение цен до 20%, но не имеют полного реестра платежей."],"stakes":"Сохранить работу больниц и законность закупок, не подменяя проверку политическим обвинением. Важны доверие к расследованию, бюджетные издержки и устойчивость кабинета.","agenda":["Кто должен проводить проверку и получит доступ к первичным документам?","Можно ли временно отстранить министра без признания его виновным?","Какие сведения разрешено обнародовать до завершения расследования?"],"task":"Согласовать позицию делегации относительно курса кабинета и предложить условия публичной проверки."},{"lead":"Кредитные агентства ухудшили прогноз по обязательствам Республики Арея. Национальная валюта резко ослабла, крупнейшие компании отложили инвестиции, а правительство готовит сокращение расходов. Министр финансов предупреждает о риске дефицита бюджета, социальные организации говорят о росте бедности.","context":"На заседание политических элит вынесены три линии поведения: жёсткая экономия, согласованный пакет поддержки и переговоров либо отказ от экономии с расширением расходов. Ни один из подходов не устраняет одновременно дефицит, инфляцию и недовольство населения. Срочные действия потребуются прежде, чем начнётся следующий бюджетный квартал.","facts":["По предварительной оценке правительства, недостающие бюджетные доходы составят около 9% плановых расходов.","Четверть крупных предприятий намерена отложить новые проекты при сохранении высокой стоимости кредитов.","Региональные власти сообщают о задержках финансирования транспорта и социальной инфраструктуры.","Кредиторы согласны начать переговоры, но требуют публичного среднесрочного плана расходов."],"uncertain":["Банк Арея прогнозирует восстановление спроса через полгода; союз предпринимателей считает этот прогноз чрезмерно оптимистичным.","Оппозиция утверждает, что часть дефицита можно закрыть пересмотром льгот, но расчёты экономии расходятся с данными казначейства."],"stakes":"Согласовать, кто понесёт первые издержки кризиса: бюджетные учреждения, предприниматели или домохозяйства. Ресурсов для полной компенсации потерь нет.","agenda":["Какие расходы сокращать в первую очередь, а какие защищать?","Какие обязательства бизнеса и правительства должны быть взаимными?","Что считать допустимой ценой переговоров с кредиторами?"],"task":"Представить антикризисную позицию и не менее одного проверяемого условия поддержки чужой программы."},{"lead":"После принятия пенсионной реформы в столице и промышленных городах проходят многотысячные демонстрации. Профсоюзы объявили предупредительные забастовки, региональные администрации сообщают о сбоях транспорта. Кабинет считает реформу необходимой, протестующие называют её несправедливой.","context":"Участники протестов не образуют единой группы: часть требует полной отмены реформы, часть готова обсуждать переходный период и компенсации. Полиция предупреждает о риске столкновений, но большинство шествий пока проходят мирно. Внутри правительства обсуждают силовые меры, переговоры и приостановку отдельных положений.","facts":["В двух промышленных регионах из-за забастовок нарушены поставки сырья на предприятия.","Согласно официальным сводкам, в нескольких городах произошли отдельные столкновения, но большинство акций не сопровождалось насилием.","Профсоюзы предлагают поэтапное повышение пенсионного возраста и льготы для тяжёлых профессий.","Бюджетный комитет заявляет, что без реформы расходы пенсионной системы будут расти быстрее доходов."],"uncertain":["Силовые структуры связывают несколько эпизодов насилия с организованными группами; доказательства публично не представлены.","Организаторы протеста заявляют о гораздо большей численности участников, чем сообщают администрации городов."],"stakes":"Право на мирный протест, работоспособность экономики и бюджетная устойчивость должны учитываться одновременно. Репрессивные меры способны временно восстановить движение, но усилить конфликт.","agenda":["Кого признать законными представителями протестующих за столом переговоров?","Какие элементы реформы можно временно заморозить?","Как отделить обеспечение безопасности от политического подавления акций?"],"task":"Выбрать политическую линию и сформулировать условия деэскалации, которые смогут поддержать другие элиты."},{"lead":"Соседнее государство ввело торговые ограничения и персональные санкции против должностных лиц Арея, обвинив республику в тайной поддержке вооружённых групп за границей. Правительство отвергает обвинения, армейское командование требует ответных мер, экспортёры предупреждают о возможном падении продаж.","context":"По дипломатическим каналам поступило предложение о встрече посредников, однако его условия не опубликованы. Внутри правящей коалиции одни считают уступки признаком слабости, другие опасаются торговой изоляции. Силовой ответ может усилить внутреннюю мобилизацию, но повысить риск случайной эскалации.","facts":["Ограничения затрагивают оборудование, необходимое двум крупным экспортным отраслям.","Часть зарубежных перевозчиков уже пересмотрела страховые тарифы; поставки пока полностью не остановлены.","Соседнее государство не разорвало дипломатические отношения и оставило канал переговоров открытым.","Совет безопасности республики не располагает подтверждёнными данными о готовящемся прямом военном нападении."],"uncertain":["Заявления о поддержке вооружённых групп основаны на материалах, которые внешняя сторона не раскрыла.","Внутри оборонного ведомства расходятся оценки последствий ограниченного демонстративного ответа."],"stakes":"Необходимо совместить безопасность, экономические связи и дипломатическую репутацию. Риторика переговоров не гарантирует отмены санкций; демонстрация силы не гарантирует сдерживания.","agenda":["Какие публичные условия переговоров приемлемы для всех делегаций?","Кто компенсирует потери компаний при сохранении ограничений?","Какие действия допустимы без перехода к вооружённому конфликту?"],"task":"Согласовать позицию относительно ответных мер и предложить механизм контроля их последствий."},{"lead":"Через три месяца в Республике Арея пройдут парламентские выборы. Рейтинг правящей коалиции снижается, а независимые наблюдатели сообщают о неравном доступе кандидатов к местным СМИ. Избирательная комиссия считает процедуры законными; оппозиция сомневается в её беспристрастности.","context":"Появились сообщения о давлении на сотрудников бюджетных учреждений и использовании служебного транспорта для предвыборной кампании. Часть сведений подтверждена документами, часть распространяется без доказательств. Пересмотр правил перед выборами повысит доверие, но может затруднить подготовку голосования.","facts":["До регистрации окончательных списков кандидатов остаётся несколько недель.","В трёх регионах зарегистрированы официальные жалобы на нарушения условий агитации.","Действующие комиссии сформированы до начала кампании, их мандат законен.","Представители малого бизнеса требуют равных условий финансирования партий и прозрачности пожертвований."],"uncertain":["Появившиеся в сети протоколы о готовящихся фальсификациях не прошли независимую проверку.","Социологические опросы дают разные оценки поддержки правящей коалиции из-за различий в методиках."],"stakes":"Выборы должны оставаться технически управляемыми, конкурентными и признанными обществом. Любое вмешательство в процедуры накануне голосования имеет собственные риски.","agenda":["Как организовать независимое наблюдение, не парализовав работу комиссий?","Нужны ли новые правила доступа кандидатов к эфиру?","Кто и как будет расследовать сообщения о нарушениях до дня голосования?"],"task":"Предложить гарантии честной кампании и договориться о механизмах публичного контроля."},{"lead":"Президент предложил конституционную реформу, расширяющую полномочия исполнительной власти и изменяющую порядок парламентского контроля. Правительство объясняет инициативу необходимостью быстрее реагировать на кризисы. Оппозиция видит угрозу концентрации власти, бизнес обеспокоен устойчивостью правовых правил.","context":"Текст проекта подготовлен ограниченной рабочей группой. Окончательное соглашение предполагает поддержку нескольких политических элит, поэтому одностороннее решение способно привести к затяжному конфликту. Ускорение принятия законов может повысить управляемость, но снизить возможности проверки решений.","facts":["Проект позволяет президенту назначать часть руководителей ведомств без прежнего согласования с парламентом.","Новые правила предусматривают изменение процедуры парламентских расследований.","Для реализации реформы необходимо юридическое оформление и соблюдение действующей процедуры изменения Конституции.","Общественные организации требуют публикации полного проекта и заключений независимых юристов."],"uncertain":["Правительство обещает, что расширенные полномочия будут временными; в имеющейся редакции проекта срок их действия сформулирован неоднозначно.","Оппозиция заявляет о риске ослабления суда, хотя соответствующие положения пока представлены лишь в рабочих материалах."],"stakes":"Выбор стоит между скоростью принятия решений, парламентским контролем и доверием к институтам. Даже формально законная реформа может оказаться политически неустойчивой.","agenda":["Какие полномочия следует ограничить по сроку и предмету?","Кто будет контролировать действия исполнительной власти?","Нужно ли широкое общественное обсуждение до голосования по проекту?"],"task":"Сформулировать позицию по реформе и минимальные институциональные гарантии, без которых делегация не поддержит соглашение."},{"lead":"На промышленном объекте у крупной реки произошла авария: нефтепродукты попали в воду и затронули три региона. Спасательные службы устанавливают защитные заграждения. Жители требуют компенсаций, компания-оператор называет ущерб локальным, а экологические организации заявляют о гораздо более серьёзных последствиях.","context":"Правительство обсуждает экстренный фонд восстановления. Бизнес опасается банкротства ряда подрядчиков, медиа добиваются полного доступа к отчётам, региональные власти просят немедленную помощь. Утечка ещё не полностью локализована, поэтому преждевременные обещания стоимости восстановления могут оказаться неверными.","facts":["В двух населённых пунктах временно ограничено использование воды из местных источников.","На предприятии выявлен сбой системы контроля давления; степень управленческой ответственности ещё устанавливается.","Компания готова финансировать первоочередные работы, но спорит с оценкой будущих компенсаций.","Экстренные службы сообщают, что без дополнительных средств очистка отдельных участков затянется."],"uncertain":["Представители компании считают загрязнение ограниченным прибрежной зоной; независимые лаборатории фиксируют загрязнение ниже по течению.","В социальных сетях публикуются фотографии гибели животных без достоверной привязки к месту и времени."],"stakes":"Придётся выбирать между скоростью восстановления, финансовой нагрузкой на предприятия и прозрачностью расследования. Сокрытие данных облегчает краткосрочный контроль ситуации, но увеличивает долгосрочный риск.","agenda":["Кто оплачивает первоочередную ликвидацию последствий?","Как обеспечить независимые замеры и открытый доступ к результатам?","Какие компенсации пострадавшим обещать сейчас, пока итоговый ущерб не установлен?"],"task":"Предложить политическое решение об ответственности, финансировании и публичной отчётности по аварии."},{"lead":"После череды кризисов большинство в парламенте перестало быть устойчивым. Несколько депутатов покинули правящую коалицию; оппозиция обсуждает вотум недоверия. Одновременно часть бизнес-сообщества требует предсказуемого кабинета, а силовые ведомства заявляют о необходимости соблюдения конституционных процедур.","context":"Возможны сохранение действующего кабинета через чрезвычайные меры, соглашение о новом коалиционном правительстве либо досрочные выборы. Однако ни один вариант не гарантирует скорой стабилизации: коалиция потребует уступок, выборы займут время, чрезвычайные меры способны вызвать протесты.","facts":["У кабинета нет гарантированной поддержки при следующем ключевом голосовании.","Оппозиция готова к переговорам о распределении министерских портфелей, но её фракции расходятся по экономической программе.","Государственный бюджет нуждается в утверждении до следующего финансового периода.","Силовые структуры публично обещают исполнение законных решений вне зависимости от состава кабинета."],"uncertain":["В прессе обсуждается возможность выхода из коалиции ещё одной группы депутатов; официального заявления нет.","Часть общественных организаций поддерживает досрочные выборы, другие опасаются новой волны дестабилизации."],"stakes":"Необходимо определить, какой механизм смены или сохранения власти будет легитимным и осуществимым. Простая победа одной делегации не решит проблему управления республикой.","agenda":["Какие гарантии получат участники коалиции и кто возьмёт ответственность за бюджет?","В каких условиях допустимы досрочные выборы, и кто обеспечит безопасность перехода?","Как будет обеспечена прозрачность переговоров о власти?"],"task":"Добиться политического соглашения о формировании власти или зафиксировать обоснованный отказ от него."}];
const TEAM_INSIDER_NOTES=[["У президентской администрации есть письмо казначейства о задержке части больничных платежей: его публикация усилит подозрения, но покажет проблемы управления.","Среди ваших сторонников есть депутаты, которые поддержат независимую комиссию, но не готовы голосовать за отставку без заключения аудиторов.","Часть ваших контрактов связана с поставщиком оборудования: немедленное расторжение грозит штрафами, а аудит может выявить нарушения.","Редакция располагает двумя независимыми источниками, но ни один не подтверждает личную выгоду министра; важно не подменить проверку обвинением.","Следователи готовы изучить документы, но требуют защиты свидетелей и исключения публичного раскрытия персональных данных."],["Минфин знает, какие статьи бюджета можно перенести без остановки социальных выплат, но прогноз по налогам остаётся неопределённым.","Две региональные фракции согласятся поддержать ограниченную экономию, если финансирование больниц сохранится.","Ассоциация работодателей готова обещать сохранение рабочих мест при доступе к гарантиям, но единых обязательств пока нет.","У редакции есть два противоречивых прогноза инфляции; один подготовлен по заказу банка, методика другого открыта.","Ведомства могут сократить часть закупок, но требуют публичного перечня критически важных функций."],["Губернаторы просят согласовать паузу в реформе, поскольку силовой ответ может усугубить региональные конфликты.","Вы можете привести представителей профсоюзов на переговоры, но они требуют письменного обязательства о пересмотре реформы.","Работодатели готовы поддержать временные компенсации рабочим, если протестующие обеспечат возвращение на предприятия.","Часть видеозаписей столкновений обрезана; редакции нужно согласовать независимую проверку с обеими сторонами.","Командиры на местах предупреждают, что применение силы без понятных правил увеличивает вероятность несоразмерных действий."],["Дипломатическая служба допускает переговоры, но не готова признать обвинения без доступа к доказательствам.","Часть парламентских комиссий поддержит оборонные расходы, но требует исключить наступательные действия.","Крупные экспортёры располагают данными о риске расторжения контрактов; переговоры о торговых исключениях требуют гарантий государства.","У журналистов есть сведения о закрытом дипломатическом предложении, но публикация деталей без согласования может сорвать контакты.","Военные считают оборонительное патрулирование достаточным на ближайший период; отдельные командиры настаивают на более жёстких сигналах."],["Администрация обладает деталями организации выборов, но их несвоевременное раскрытие вызовет подозрения в изменении правил.","Наблюдательские группы согласны сотрудничать, если будут иметь доступ к процедурам регистрации и подсчёта.","Ряд доноров опасается огласки пожертвований; прозрачные правила снизят коррупционный риск, но сократят финансирование.","В редакцию поступил неподтверждённый протокол возможных нарушений: до публикации требуется проверка происхождения.","На местах участились жалобы на давление на наблюдателей; силовые структуры могут согласовать общий протокол реагирования."],["Аппарат президента готов ограничить срок действия части новых полномочий, если парламент поддержит реформу.","Ваша фракция согласится на временные чрезвычайные полномочия только с парламентским пересмотром и судебным контролем.","Бизнес заинтересован в стабильности правил разрешения споров и будет поддерживать реформу лишь при сохранении судебных гарантий.","Несколько правоведов готовы публично разобрать проект, но им необходим полный текст, а не тезисы администрации.","Ведомства не заинтересованы в смене правил под конкретного министра и могут поддержать нейтральные процедуры контроля."],["Экстренный бюджет ограничен: правительству нужно решить, что оплатить немедленно, а что взыскать с виновного позднее.","У местных жителей есть коллективные иски; помощь с экспертизой может повысить доверие, но требует времени.","Компания располагает внутренними замерами, пока не опубликованными; их раскрытие уменьшит риск слухов, но повысит юридические издержки.","У редакции есть данные одной независимой лаборатории и отказ предприятия раскрыть методику собственных замеров.","Следователи и спасатели спорят о границах опасной зоны: необходим единый протокол доступа и отбора проб."],["У действующего кабинета ещё есть возможность предложить оппозиции должности и конкретные условия бюджетного соглашения.","Внутри оппозиции нет согласия об экономических приоритетах будущего кабинета; это слабое место переговоров.","Финансовые организации требуют гарантий выполнения контрактов при любом результате, но не готовы публично поддерживать одну группу.","Редакции поступила информация о закрытых переговорах о должностях; публикация без подтверждения может сорвать компромисс.","Руководство силовых ведомств обязалось соблюдать законный порядок перехода власти; часть политиков пытается добиться публичной поддержки силовиков."]];
