const ALIGNED_GOALS=[[1,2,1,2,1],[1,2,1,2,1],[1,2,1,2,1],[1,1,1,2,1],[1,2,1,2,1],[1,2,1,2,1],[1,2,1,2,1],[1,2,1,2,1]];
const isAlignedCurrent=(s:any)=>s.round >= (s.alignedFromRound??(s.phase==='lobby'?0:99));
const usesBalancedEffects=(s:any)=>isAlignedCurrent(s)&&s.round>=(s.effectsFromRound??(s.phase==='lobby'?0:99));
const roundFor=(s:any)=>isAlignedCurrent(s)?{...rounds[s.round],options:ALIGNED_NATIONAL_OPTIONS[s.round].map((opt:any,i:number)=>[opt[0],usesBalancedEffects(s)?BALANCED_NATIONAL_EFFECTS[s.round][i]:opt[1]])}:rounds[s.round];
function alignedImpact(round:number,team:number,option:number){return team===3?ALIGNED_MEDIA_IMPACT[round][option]:ALIGNED_ROLE_IMPACT[team][option];}
function balancedRoleImpact(s:any,team:number,option:number){return usesBalancedEffects(s)?BALANCED_ROLE_IMPACT[s.round][effectiveRole(s,team)][option]:alignedImpact(s.round,effectiveRole(s,team),option);}
function strategyFor(s:any,team:number){return isAlignedCurrent(s)?ALIGNED_GOALS[s.round][effectiveRole(s,team)]:strategicOption(s.round,team);}
function currentOptions(s:any,tid:number){const national=roundFor(s).options;if(!isRoleCurrent(s))return national.map((x:any)=>x[0]);return isAlignedCurrent(s)?ALIGNED_ROLE_CHOICES[s.round][effectiveRole(s,tid)]:ROLE_CHOICES[s.round][tid];}
const missions=['Не менее трёх раз выбрать наиболее устойчивый курс управления','Не менее трёх раз отстоять альтернативную программу','Не менее трёх раз выбрать экономически эффективную стратегию','Не менее трёх раз выбрать стратегию общественной прозрачности','Не менее трёх раз выбрать стратегию защиты стабильности'];
const GOAL_MATRIX=[[2,2,2,0,2],[2,1,1,2,2],[0,0,2,0,0],[0,0,0,0,0],[0,2,2,0,2],[1,1,1,1,1],[2,2,2,0,2],[0,0,0,0,0]];
function strategicOption(round:number,team:number){return GOAL_MATRIX[round][team];}
function leadingChoice(choices:number[],round:number,nationalOptions:any=rounds[round].options){const counts=[0,0,0];choices.forEach(x=>{if(x>=0&&x<3)counts[x]++});const max=Math.max(...counts);if(max===0)return 0;const candidates=[0,1,2].filter(x=>counts[x]===max);if(candidates.length===1)return candidates[0];const utility=(k:number)=>nationalOptions[k][1].reduce((sum:number,v:number)=>sum+v,0);return candidates.sort((a,b)=>utility(b)-utility(a)||a-b)[0];}
